from test_helpers import test,solo

observed=solo+"C_UnitAuras.GetAuraCasterGUID=function() return 'Player-Driveby' end; auras.player={{spellId=1459,auraInstanceID=88}}; "
test('Reported name-only driveby never calls the emote API',observed+"UnitNameFromGUID=function() return 'Themfatale','Fabulous' end; BuffTap:ObserveSoloThanks(); advance(.3); assert(#emotes==0 and BuffTap.helperThankStatus:find('no live unit',1,true))")
test('Readable name never goes to emote API even if API would accept it',observed+"local calls=0; UnitNameFromGUID=function() return 'Themfatale','Fabulous' end; C_ChatInfo={PerformEmote=function() calls=calls+1; return false end}; BuffTap:ObserveSoloThanks(); advance(.3); assert(calls==0)")
native=observed+"local old=UnitGUID; UnitGUID=function(u) return u=='target' and 'Player-Driveby' or old(u) end; UnitTokenFromGUID=function(g) assert(g=='Player-Driveby'); return 'target' end; "
test('Native GUID lookup resolves verified live provider',native+"BuffTap:ObserveSoloThanks(); assert(#emotes==1 and emotes[1][2]=='target' and BuffTap.helperThankStatus:find('aura GUID / live unit',1,true))")
for value in ['nil','{secret=true}']:
 test('Missing or secret native token remains silent '+value,observed+"UnitTokenFromGUID=function() return "+value+" end; BuffTap:ObserveSoloThanks(); assert(#emotes==0)")
test('Throwing native token lookup remains silent',observed+"UnitTokenFromGUID=function() error('restricted') end; BuffTap:ObserveSoloThanks(); assert(#emotes==0)")
test('Wrong GUID returned by native token lookup is refused',observed+"UnitTokenFromGUID=function() return 'target' end; BuffTap:ObserveSoloThanks(); assert(#emotes==0)")
test('Native token still needs a current unit',native+"local oldExists=UnitExists; UnitExists=function(u) return u~='target' and oldExists(u) end; BuffTap:ObserveSoloThanks(); assert(#emotes==0)")
test('Native lookup can find a unit outside enumerated plate list',observed+"local oldE,oldG,oldN=UnitExists,UnitGUID,UnitName; UnitExists=function(u) return u=='nameplate99' or oldE(u) end; UnitGUID=function(u) return u=='nameplate99' and 'Player-Driveby' or oldG(u) end; UnitName=function(u) if u=='nameplate99' then return 'Themfatale','Fabulous' end return oldN(u) end; UnitTokenFromGUID=function() return 'nameplate99' end; BuffTap:ObserveSoloThanks(); assert(#emotes==1 and emotes[1][2]=='nameplate99')")
test('Briefly delayed native unit can settle into directed thanks',native+"local token; UnitTokenFromGUID=function() return token end; local oldE=UnitExists; UnitExists=function(u) return u~='target' and oldE(u) end; BuffTap:ObserveSoloThanks(); assert(#emotes==0); UnitExists=oldE; token='target'; advance(.3); assert(#emotes==1 and emotes[1][2]=='target')")
test('Legacy queued name-only record cannot emit a general emote',solo+"BuffTap.helperThankQueue={{guid='Player-Driveby',name='Themfatale-Fabulous',key='guid:Player-Driveby',nameKey='name:Themfatale-Fabulous',at=now,identity='aura GUID / name'}}; BuffTap:DispatchSoloThanks(); assert(#emotes==0 and #BuffTap.helperThankQueue==0)")
test('Caster leaving before queued dispatch cannot emit a general emote',solo+"received(1459,'target'); received(1243,'party1'); local old=UnitExists; UnitExists=function(u) return u~='party1' and old(u) end; advance(1.1); assert(#emotes==1 and BuffTap.helperThankStatus:find('identity changed',1,true))")
test('Unavailable caster cannot fall back to current hostile or other target',observed+"UnitNameFromGUID=function() return 'Themfatale','Fabulous' end; BuffTap:ObserveSoloThanks(); for i=1,15 do advance(.21) end; assert(#emotes==0 and not BuffTap.helperThankRetryPending)")
